<script lang="ts">
 import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createManagedUsersState} from '../state/managedUsersState.svelte';import type {ManagedUser,CreateManagedUser,UpdateManagedUser} from '../../domain/entity/UserManagement';
 const i18n=getContext<I18nState>('i18n');const vm=createManagedUsersState();let formOpen=$state(false),editing=$state<ManagedUser|null>(null),username=$state(''),password=$state(''),fullName=$state(''),role=$state<'ADMIN'|'USER'>('USER'),warehouseIds=$state(''),allowedFunctions=$state(''),isActive=$state(true),permissionUser=$state<ManagedUser|null>(null),pageKeys=$state('');
 onMount(()=>{void vm.load();});
 function reset(){formOpen=false;editing=null;username='';password='';fullName='';role='USER';warehouseIds='';allowedFunctions='';isActive=true;}
 function edit(u:ManagedUser){editing=u;username=u.username;fullName=u.fullName;role=u.role;warehouseIds=u.warehouseIds.join(',');allowedFunctions=u.allowedFunctions.join(',');isActive=u.isActive;password='';formOpen=true;}
 function nums(v:string){return v.split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>0);}
 function words(v:string){return v.split(',').map(x=>x.trim()).filter(Boolean);}
 async function save(){if(editing){const v:UpdateManagedUser={userId:editing.userId,fullName,role,warehouseIds:nums(warehouseIds),allowedFunctions:words(allowedFunctions),isActive,password:password||undefined};if(await vm.update(v))reset();}else{const v:CreateManagedUser={username,password,fullName,role,warehouseIds:nums(warehouseIds),allowedFunctions:words(allowedFunctions)};if(await vm.create(v))reset();}}
 async function openPermissions(u:ManagedUser){permissionUser=u;const p=await vm.loadPermissions(u.userId);pageKeys=p?.pageKeys.join(', ')??'';}
 async function savePermissions(){if(permissionUser&&await vm.savePermissions(permissionUser.userId,words(pageKeys)))permissionUser=null;}
 async function remove(u:ManagedUser){if(confirm('¿Eliminar el usuario '+u.username+'?'))await vm.remove(u.userId);}
</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Usuarios y permisos')}</h1><p>{i18n.t('Administra cuentas, almacenes asignados y permisos de acceso.')}</p></div><button class="primary" onclick={()=>{reset();formOpen=true;}}>{i18n.t('Nuevo usuario')}</button></header>
{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if formOpen}<form class="editor" onsubmit={e=>{e.preventDefault();void save();}}><h2>{editing?i18n.t('Editar usuario'):i18n.t('Nuevo usuario')}</h2>
{#if !editing}<label>{i18n.t('Usuario')} *<input required maxlength="150" bind:value={username}/></label>{/if}
<label>{i18n.t('Nombre completo')} *<input required maxlength="256" bind:value={fullName}/></label><label>{i18n.t('Contraseña')}{#if !editing} *{/if}<input type="password" bind:value={password} required={!editing}/></label>
<label>{i18n.t('Rol')}<select bind:value={role}><option value="USER">USER</option><option value="ADMIN">ADMIN</option></select></label><label>{i18n.t('Almacenes (IDs separados por coma)')}<input bind:value={warehouseIds}/></label><label>{i18n.t('Funciones especiales (separadas por coma)')}<input bind:value={allowedFunctions}/></label>
{#if editing}<label class="check"><input type="checkbox" bind:checked={isActive}/>{i18n.t('Activo')}</label>{/if}
<div class="actions"><button type="button" onclick={reset}>{i18n.t('Cancelar')}</button><button class="primary" type="submit" disabled={vm.saving}>{i18n.t('Guardar')}</button></div></form>{/if}
{#if permissionUser}<form class="editor" onsubmit={e=>{e.preventDefault();void savePermissions();}}><h2>{i18n.t('Permisos de')} {permissionUser.username}</h2><label>{i18n.t('Claves de página separadas por coma')}<textarea rows="4" bind:value={pageKeys} disabled={vm.permissions?.isFullAccess}/></label><p class="hint">{i18n.t('ADMIN tiene acceso total; las claves se validan en el backend.')}</p><div class="actions"><button type="button" onclick={()=>permissionUser=null}>{i18n.t('Cerrar')}</button><button class="primary" type="submit" disabled={vm.saving||vm.permissions?.isFullAccess}>{i18n.t('Guardar permisos')}</button></div></form>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Usuario')}</th><th>{i18n.t('Nombre')}</th><th>{i18n.t('Rol')}</th><th>{i18n.t('Almacenes')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Último acceso')}</th><th>{i18n.t('Acciones')}</th></tr></thead><tbody>{#each vm.users as u (u.userId)}<tr><td>{u.username}</td><td>{u.fullName}</td><td>{u.role}</td><td>{u.warehouseIds.join(', ')||'—'}</td><td>{u.isActive?i18n.t('Activo'):i18n.t('Inactivo')}</td><td>{u.lastLogin??'—'}</td><td><button onclick={()=>edit(u)}>{i18n.t('Editar')}</button><button onclick={()=>void openPermissions(u)}>{i18n.t('Permisos')}</button><button class="danger" onclick={()=>void remove(u)} disabled={vm.saving}>{i18n.t('Eliminar')}</button></td></tr>{/each}</tbody></table></div>{/if}
</section>
<style>
.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1.2rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.55rem .8rem;background:var(--card);color:var(--ink);cursor:pointer;margin-right:.3rem}.primary{background:var(--navy);color:white;border-color:var(--navy)}.danger,.error{color:var(--danger)}.editor{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--card);margin-bottom:1rem}.editor h2,.editor p,.actions{grid-column:1/-1}.editor h2{margin:0;font-size:1rem}.editor label{display:grid;gap:.35rem;color:var(--slate);font-size:.8rem}.editor input,.editor select,.editor textarea{min-height:39px;border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;background:var(--card);color:var(--ink);font:inherit}.editor .check{display:flex;align-items:center}.editor .check input{min-height:auto}.actions{display:flex;justify-content:flex-end}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card)}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.84rem}th,td{text-align:left;padding:.7rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.72rem;text-transform:uppercase}.hint{color:var(--slate);font-size:.8rem}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.editor{grid-template-columns:1fr}}
</style>